CREATE TABLE room_comment (id UUID PRIMARY KEY DEFAULT uuid_v7(),room_id UUID NOT NULL,author_id UUID NOT NULL,idempotency_key VARCHAR(256) NOT NULL,body TEXT NOT NULL,deleted BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(room_id) REFERENCES room(id)); CREATE UNIQUE INDEX uq_room_comment_idempotency ON room_comment(room_id,author_id,idempotency_key); CREATE INDEX idx_room_comment_timeline ON room_comment(room_id,created_at,id);
